import com.wolinski.shop.platform.ShopProblem;

/** Turns a percentage typed into a form, such as "12.5", into whole basis points (1250). */
final class PercentRate {

    static final long ONE_HUNDRED_PERCENT = 10_000;

    private static final int MAX_WHOLE_DIGITS = 5;

    private PercentRate() {
    }

    /**
     * Accepts digits, optionally with a decimal point followed by at most two digits.
     * Anything else, or a value outside 0 to 100 inclusive, is refused.
     */
    static long parseBasisPoints(String text) {
        if (null == text) {
            throw invalid(null);
        }
        String s = text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);

        if (whole.isEmpty() && fraction.isEmpty()) {
            throw invalid(text);
        }
        if (whole.length() > MAX_WHOLE_DIGITS || fraction.length() > 2) {
            throw invalid(text);
        }
        if (!allDigits(whole) || !allDigits(fraction)) {
            throw invalid(text);
        }

        long wholeValue = whole.isEmpty() ? 0 : Long.parseLong(whole);
        long fractionValue = Long.parseLong((fraction + "00").substring(0, 2));
        long basisPoints = wholeValue * 100 + fractionValue;

        if (basisPoints > ONE_HUNDRED_PERCENT) {
            throw invalid(text);
        }
        return basisPoints;
    }

    private static boolean allDigits(String digits) {
        for (int i = 0; i < digits.length(); i++) {
            char c = digits.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static ShopProblem invalid(String text) {
        return new ShopProblem("INVALID_PERCENT",
                "A discount must be a percentage from 0 to 100 with at most two decimals, got: " + text);
    }
}
}

