import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class PercentRateTest {

    @Test
    void parsesWholeAndFractionalPercentsIntoBasisPoints() {
        assertEquals(1250, PercentRate.parseBasisPoints("12.5"));
        assertEquals(50, PercentRate.parseBasisPoints("0.5"));
        assertEquals(1200, PercentRate.parseBasisPoints("12"));
        assertEquals(1200, PercentRate.parseBasisPoints("12."));
        assertEquals(15, PercentRate.parseBasisPoints(".15"));
        assertEquals(10_000, PercentRate.parseBasisPoints("100"));
        assertEquals(0, PercentRate.parseBasisPoints(" 0 "));
    }

    @ParameterizedTest
    @ValueSource(strings = {"", " ", ".", "-1", "+5", "101", "100.01", "1.234", "1,5", "abc", "1e2", "12%"})
    void refusesMalformedOrOutOfRangePercents(String text) {
        ShopProblem problem = assertThrows(ShopProblem.class, () -> PercentRate.parseBasisPoints(text));
        assertEquals("INVALID_PERCENT", problem.code());
    }

    @Test
    void refusesNull() {
        assertThrows(ShopProblem.class, () -> PercentRate.parseBasisPoints(null));
    }
}
}
